{"version":3,"file":"publish.js","sources":["pages/publish/publish.vue","../../../Downloads/HBuilderX.5.07.2026041006/HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvcHVibGlzaC9wdWJsaXNoLnZ1ZQ"],"sourcesContent":["<template>\r\n  <view class=\"publish-page\">\r\n    <view class=\"modern-card form-wrap\">\r\n      <uni-forms ref=\"formRef\" :model=\"formData\" :rules=\"rules\" label-position=\"top\">\r\n        <uni-forms-item label=\"出发地\" name=\"start\" required>\r\n          <view class=\"location-picker text-main\" @click=\"pickLocation('start')\">{{ formData.start || '点击选择出发地' }}</view>\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"目的地\" name=\"end\" required>\r\n          <view class=\"location-picker text-main\" @click=\"pickLocation('end')\">{{ formData.end || '点击选择目的地' }}</view>\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"出发时间\" name=\"time\" required>\r\n          <uni-datetime-picker type=\"datetime\" v-model=\"formData.time\" />\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"提供座位数\" name=\"seats\" required>\r\n          <uni-number-box v-model=\"formData.seats\" :min=\"1\" :max=\"6\" />\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"预期分摊(元/人)\" name=\"price\" required>\r\n          <uni-easyinput v-model=\"formData.price\" type=\"digit\" placeholder=\"输入金额\" />\r\n        </uni-forms-item>\r\n      </uni-forms>\r\n    </view>\r\n    <button class=\"modern-btn publish-btn\" @click=\"submit\">确认发布</button>\r\n  </view>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref } from 'vue'\r\nimport { useRideStore } from '@/stores/ride'\r\nimport { useUserStore } from '@/stores/user'\r\n\r\nconst rideStore = useRideStore()\r\nconst userStore = useUserStore()\r\nconst formRef = ref(null)\r\n\r\nconst formData = ref({ start: '', end: '', time: '', seats: 1, price: '', lat: 22.54, lng: 113.93 })\r\n\r\nconst rules = {\r\n  start: { rules: [{ required: true, errorMessage: '请选择出发地' }] },\r\n  end: { rules: [{ required: true, errorMessage: '请选择目的地' }] },\r\n  time: { rules: [{ required: true, errorMessage: '请选择时间' }] },\r\n  price: { rules: [{ required: true, errorMessage: '请填写金额' }] }\r\n}\r\n\r\nconst pickLocation = (field) => {\r\n  uni.chooseLocation({\r\n    success: (res) => {\r\n      formData.value[field] = res.name\r\n      if (field === 'start') { formData.value.lat = res.latitude; formData.value.lng = res.longitude }\r\n    }\r\n  })\r\n}\r\n\r\nconst submit = () => {\r\n  if (!userStore.isLogged) return uni.navigateTo({ url: '/pages/login/login' })\r\n  if (!userStore.userInfo.isCertified) return uni.showToast({ title: '请先完成车主认证', icon: 'none' })\r\n\r\n  formRef.value.validate().then(() => {\r\n    uni.showLoading({ title: '发布中' })\r\n    setTimeout(() => {\r\n      rideStore.publishRide(formData.value)\r\n      uni.hideLoading()\r\n      uni.showToast({ title: '发布成功' })\r\n      setTimeout(() => uni.switchTab({ url: '/pages/index/index' }), 1500)\r\n    }, 1000)\r\n  }).catch(() => {})\r\n}\r\n</script>\r\n\r\n<style lang=\"scss\" scoped>\r\n.publish-page { padding: 30rpx; }\r\n.form-wrap { padding: 40rpx; margin-bottom: 40rpx; }\r\n.location-picker { padding: 20rpx; background: var(--pc-bg); border-radius: 12rpx; border: 1px solid var(--pc-border); min-height: 80rpx; display: flex; align-items: center; }\r\n.publish-btn { width: 100%; height: 90rpx; line-height: 90rpx; font-size: 34rpx; }\r\n</style>","import MiniProgramPage from 'C:/Users/16947/CodeBuddy/MUST-Carpool-WeChat/MUST-GO/pages/publish/publish.vue'\nwx.createPage(MiniProgramPage)"],"names":["useRideStore","useUserStore","ref","uni"],"mappings":";;;;;;;;;;;;;;;;;;;;;;;AA8BA,UAAM,YAAYA,YAAAA,aAAc;AAChC,UAAM,YAAYC,YAAAA,aAAc;AAChC,UAAM,UAAUC,cAAG,IAAC,IAAI;AAExB,UAAM,WAAWA,cAAG,IAAC,EAAE,OAAO,IAAI,KAAK,IAAI,MAAM,IAAI,OAAO,GAAG,OAAO,IAAI,KAAK,OAAO,KAAK,QAAQ;AAEnG,UAAM,QAAQ;AAAA,MACZ,OAAO,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,SAAQ,CAAE,EAAG;AAAA,MAC9D,KAAK,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,SAAQ,CAAE,EAAG;AAAA,MAC5D,MAAM,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,QAAO,CAAE,EAAG;AAAA,MAC5D,OAAO,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,QAAO,CAAE,EAAG;AAAA,IAC/D;AAEA,UAAM,eAAe,CAAC,UAAU;AAC9BC,oBAAAA,MAAI,eAAe;AAAA,QACjB,SAAS,CAAC,QAAQ;AAChB,mBAAS,MAAM,KAAK,IAAI,IAAI;AAC5B,cAAI,UAAU,SAAS;AAAE,qBAAS,MAAM,MAAM,IAAI;AAAU,qBAAS,MAAM,MAAM,IAAI;AAAA,UAAW;AAAA,QACjG;AAAA,MACL,CAAG;AAAA,IACH;AAEA,UAAM,SAAS,MAAM;AACnB,UAAI,CAAC,UAAU;AAAU,eAAOA,cAAAA,MAAI,WAAW,EAAE,KAAK,sBAAsB;AAC5E,UAAI,CAAC,UAAU,SAAS;AAAa,eAAOA,cAAG,MAAC,UAAU,EAAE,OAAO,YAAY,MAAM,OAAM,CAAE;AAE7F,cAAQ,MAAM,SAAU,EAAC,KAAK,MAAM;AAClCA,sBAAAA,MAAI,YAAY,EAAE,OAAO,MAAK,CAAE;AAChC,mBAAW,MAAM;AACf,oBAAU,YAAY,SAAS,KAAK;AACpCA,wBAAAA,MAAI,YAAa;AACjBA,wBAAAA,MAAI,UAAU,EAAE,OAAO,OAAM,CAAE;AAC/B,qBAAW,MAAMA,cAAAA,MAAI,UAAU,EAAE,KAAK,qBAAoB,CAAE,GAAG,IAAI;AAAA,QACpE,GAAE,GAAI;AAAA,MACX,CAAG,EAAE,MAAM,MAAM;AAAA,OAAE;AAAA,IACnB;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AChEA,GAAG,WAAW,eAAe;"}
