{"version":3,"file":"publish.js","sources":["pages/publish/publish.vue","../../../HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvcHVibGlzaC9wdWJsaXNoLnZ1ZQ"],"sourcesContent":["<template>\r\n  <view class=\"publish-page\">\r\n    <view class=\"modern-card form-wrap\">\r\n      <uni-forms ref=\"formRef\" :model=\"formData\" :rules=\"rules\" label-position=\"top\">\r\n        <uni-forms-item label=\"出发地\" name=\"start\" required>\r\n          <view class=\"location-picker text-main\" @click=\"pickLocation('start')\">{{ formData.start || '点击选择出发地' }}</view>\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"目的地\" name=\"end\" required>\r\n          <view class=\"location-picker text-main\" @click=\"pickLocation('end')\">{{ formData.end || '点击选择目的地' }}</view>\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"出发时间\" name=\"time\" required>\r\n          <uni-datetime-picker type=\"datetime\" v-model=\"formData.time\" />\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"提供座位数\" name=\"seats\" required>\r\n          <uni-number-box v-model=\"formData.seats\" :min=\"1\" :max=\"6\" />\r\n        </uni-forms-item>\r\n        <uni-forms-item label=\"预期分摊(元/人)\" name=\"price\" required>\r\n          <uni-easyinput v-model=\"formData.price\" type=\"digit\" placeholder=\"输入金额\" />\r\n        </uni-forms-item>\r\n      </uni-forms>\r\n    </view>\r\n    <button class=\"modern-btn publish-btn\" @click=\"submit\">确认发布</button>\r\n  </view>\r\n</template>\r\n\r\n<script setup>\nimport { ref, reactive } from 'vue'\nimport { useRideStore } from '@/stores/ride'\nimport { useUserStore } from '@/stores/user'\n\nconst rideStore = useRideStore()\nconst userStore = useUserStore()\nconst formRef = ref(null)\nconst isSubmitting = ref(false) // 新增：提交锁，防止重复发布\n\n// 优化1：完善数据结构，同时存储起点和终点的坐标及详细地址\nconst formData = reactive({ \n  start: '', \n  end: '', \n  time: '', \n  seats: 1, \n  price: '',\n  start_location: { lat: null, lng: null, address: '' },\n  end_location: { lat: null, lng: null, address: '' }\n})\n\nconst rules = {\n  start: { rules: [{ required: true, errorMessage: '请选择出发地' }] },\n  end: { rules: [{ required: true, errorMessage: '请选择目的地' }] },\n  time: { \n    rules: [\n      { required: true, errorMessage: '请选择时间' },\n      // 优化2：功能逻辑校验，禁止发布过去的时间\n      { validateFunction: (rule, value, data, callback) => {\n          if (new Date(value).getTime() < Date.now()) callback('出发时间不能早于当前时间')\n          return true\n      }}\n    ] \n  },\n  price: { \n    rules: [\n      { required: true, errorMessage: '请填写金额' },\n      { validateFunction: (rule, value, data, callback) => {\n          if (parseFloat(value) <= 0) callback('金额必须大于0')\n          return true\n      }}\n    ] \n  }\n}\n\nconst pickLocation = (field) => {\n  uni.chooseLocation({\n    success: (res) => {\n      formData[field] = res.name\n      // 优化3：完整记录经纬度信息，这是后续“匹配算法”计算成功率的核心数据\n      formData[`${field}_location`] = {\n        lat: res.latitude,\n        lng: res.longitude,\n        address: res.address\n      }\n    },\n    fail: (err) => {\n      // 优化4：权限拒绝后的功能引导\n      if (err.errMsg.includes('auth deny')) {\n        uni.showModal({\n          title: '提示',\n          content: '请在设置中开启定位权限以选择地点',\n          success: (res) => { if (res.confirm) uni.openSetting() }\n        })\n      }\n    }\n  })\n}\n\nconst submit = async () => {\n  if (isSubmitting.value) return // 防抖锁\n  \n  if (!userStore.isLogged) return uni.navigateTo({ url: '/pages/login/login' })\n  if (!userStore.userInfo.isCertified) return uni.showToast({ title: '请先完成车主认证', icon: 'none' })\n\n  try {\n    await formRef.value.validate()\n    isSubmitting.value = true // 开启提交锁[cite: 1]\n    \n    uni.showLoading({ title: '发布中', mask: true })\n    \n    // 优化5：将提交逻辑改为异步处理，并清理过期数据[cite: 1]\n    const success = await rideStore.publishRide({ ...formData })\n    \n    uni.hideLoading()\n    if (success) {\n      uni.showToast({ title: '发布成功', icon: 'success' })\n      // 延时跳转，确保用户看到成功状态\n      setTimeout(() => {\n        isSubmitting.value = false\n        uni.switchTab({ url: '/pages/index/index' })\n      }, 1500)\n    }\n  } catch (error) {\n    isSubmitting.value = false\n    console.error('校验失败:', error)\n  }\n}\n</script>","import MiniProgramPage from 'C:/Users/窦闿元/Desktop/MUST-GO/MUST-Carpool-WeChat/MUST-GO/pages/publish/publish.vue'\nwx.createPage(MiniProgramPage)"],"names":["useRideStore","useUserStore","ref","reactive","uni","MiniProgramPage"],"mappings":";;;;;;;;;;;;;;;;;;;;;;;AA8BA,UAAM,YAAYA,YAAAA,aAAc;AAChC,UAAM,YAAYC,YAAAA,aAAc;AAChC,UAAM,UAAUC,cAAG,IAAC,IAAI;AACxB,UAAM,eAAeA,cAAG,IAAC,KAAK;AAG9B,UAAM,WAAWC,cAAAA,SAAS;AAAA,MACxB,OAAO;AAAA,MACP,KAAK;AAAA,MACL,MAAM;AAAA,MACN,OAAO;AAAA,MACP,OAAO;AAAA,MACP,gBAAgB,EAAE,KAAK,MAAM,KAAK,MAAM,SAAS,GAAI;AAAA,MACrD,cAAc,EAAE,KAAK,MAAM,KAAK,MAAM,SAAS,GAAI;AAAA,IACrD,CAAC;AAED,UAAM,QAAQ;AAAA,MACZ,OAAO,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,SAAQ,CAAE,EAAG;AAAA,MAC9D,KAAK,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,SAAQ,CAAE,EAAG;AAAA,MAC5D,MAAM;AAAA,QACJ,OAAO;AAAA,UACL,EAAE,UAAU,MAAM,cAAc,QAAS;AAAA;AAAA,UAEzC,EAAE,kBAAkB,CAAC,MAAM,OAAO,MAAM,aAAa;AACjD,gBAAI,IAAI,KAAK,KAAK,EAAE,QAAO,IAAK,KAAK,IAAG;AAAI,uBAAS,cAAc;AACnE,mBAAO;AAAA,UACjB,EAAO;AAAA,QACF;AAAA,MACF;AAAA,MACD,OAAO;AAAA,QACL,OAAO;AAAA,UACL,EAAE,UAAU,MAAM,cAAc,QAAS;AAAA,UACzC,EAAE,kBAAkB,CAAC,MAAM,OAAO,MAAM,aAAa;AACjD,gBAAI,WAAW,KAAK,KAAK;AAAG,uBAAS,SAAS;AAC9C,mBAAO;AAAA,UACjB,EAAO;AAAA,QACF;AAAA,MACF;AAAA,IACH;AAEA,UAAM,eAAe,CAAC,UAAU;AAC9BC,oBAAAA,MAAI,eAAe;AAAA,QACjB,SAAS,CAAC,QAAQ;AAChB,mBAAS,KAAK,IAAI,IAAI;AAEtB,mBAAS,GAAG,KAAK,WAAW,IAAI;AAAA,YAC9B,KAAK,IAAI;AAAA,YACT,KAAK,IAAI;AAAA,YACT,SAAS,IAAI;AAAA,UACd;AAAA,QACF;AAAA,QACD,MAAM,CAAC,QAAQ;AAEb,cAAI,IAAI,OAAO,SAAS,WAAW,GAAG;AACpCA,0BAAAA,MAAI,UAAU;AAAA,cACZ,OAAO;AAAA,cACP,SAAS;AAAA,cACT,SAAS,CAAC,QAAQ;AAAE,oBAAI,IAAI;AAASA,gCAAAA,MAAI;cAAe;AAAA,YAClE,CAAS;AAAA,UACF;AAAA,QACF;AAAA,MACL,CAAG;AAAA,IACH;AAEA,UAAM,SAAS,YAAY;AACzB,UAAI,aAAa;AAAO;AAExB,UAAI,CAAC,UAAU;AAAU,eAAOA,cAAAA,MAAI,WAAW,EAAE,KAAK,sBAAsB;AAC5E,UAAI,CAAC,UAAU,SAAS;AAAa,eAAOA,cAAG,MAAC,UAAU,EAAE,OAAO,YAAY,MAAM,OAAM,CAAE;AAE7F,UAAI;AACF,cAAM,QAAQ,MAAM,SAAU;AAC9B,qBAAa,QAAQ;AAErBA,sBAAG,MAAC,YAAY,EAAE,OAAO,OAAO,MAAM,MAAM;AAG5C,cAAM,UAAU,MAAM,UAAU,YAAY,EAAE,GAAG,SAAQ,CAAE;AAE3DA,sBAAAA,MAAI,YAAa;AACjB,YAAI,SAAS;AACXA,wBAAG,MAAC,UAAU,EAAE,OAAO,QAAQ,MAAM,WAAW;AAEhD,qBAAW,MAAM;AACf,yBAAa,QAAQ;AACrBA,0BAAAA,MAAI,UAAU,EAAE,KAAK,qBAAoB,CAAE;AAAA,UAC5C,GAAE,IAAI;AAAA,QACR;AAAA,MACF,SAAQ,OAAO;AACd,qBAAa,QAAQ;AACrBA,sBAAAA,yDAAc,SAAS,KAAK;AAAA,MAC7B;AAAA,IACH;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ACzHA,GAAG,WAAWC,SAAe;"}
